import build from '@hono/vite-build/cloudflare-pages'
import devServer from '@hono/vite-dev-server'
import adapter from '@hono/vite-dev-server/cloudflare'
import { defineConfig } from 'vite'
import { createHash } from 'node:crypto'
import { existsSync, readFileSync } from 'node:fs'

// The version on every /css/tailwind.css link (TW_CSS in src/index.tsx). The file
// is generated by `npm run css` just before this build, so its hash changes
// exactly when its content does. 'dev' only when it has not been built yet.
const TW = 'public/css/tailwind.css'
const twHash = existsSync(TW) ? createHash('sha256').update(readFileSync(TW)).digest('hex').slice(0, 10) : 'dev'

export default defineConfig({
  define: { __TW_CSS_HASH__: JSON.stringify(twHash) },
  plugins: [
    build(),
    devServer({
      adapter,
      entry: 'src/index.tsx'
    })
  ]
})
